    const email = typeof store?.id_token === 'string' ? jwtClaims(store.id_token)?.email : null;
    return typeof email === 'string' && email.length <= 254 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ? email : null;
  } catch { return null; }
