const kindFor = (tool: StoredLoginTool, key: string): StoredLoginKind | null =>
  (Object.entries(KEYS[tool]) as Array<[StoredLoginKind, string[]]>).find(([, keys]) => keys.includes(key))?.[0] ?? null;
