/** The email a profile's stored login belongs to, read locally without contacting the provider. */
export async function storedLoginEmail(profile: Pick<StoredLoginProfile, 'provider' | 'login' | 'dataDir' | 'entryId'>): Promise<string | null> {
  const entry = (await readEntries(profile.provider, profile.dataDir)).find((item) => item.kind === profile.login && (!profile.entryId || item.entryId === profile.entryId));
  return entry?.email ?? null;
}

