export type UsageProvider = 'codex-chatgpt' | 'claude-code' | 'antigravity' | 'cursor' | 'cursor-local' | 'factory-droid' | 'amp' | 'devin' | 'pi' | 'opencode' | 'omp' | 'hermes';
