import { spawn } from 'node:child_process';
import { stat } from 'node:fs/promises';
import { resolve } from 'node:path';
import { createInterface } from 'node:readline';
import { CODEX_LIMIT_REASONS, isEmail, type CodexLimitReason, type UsageAccount, type UsageProfile, type UsageWindow } from './index.js';

type RecordValue = Record<string, unknown>;
const object = (value: unknown): RecordValue | null => value && typeof value === 'object' && !Array.isArray(value) ? value as RecordValue : null;
const number = (value: unknown): number | null => typeof value === 'number' && Number.isFinite(value) ? value : null;
const string = (value: unknown, max = 128): string | null => typeof value === 'string' && value.length > 0 && value.length <= max && !/[\x00-\x1f\x7f]/.test(value) ? value : null;
const timestamp = (value: unknown): string | null => {
  const seconds = number(value);
  if (seconds === null || seconds < 0 || seconds > 253402300799) return null;
  const date = new Date(seconds * 1000);
  return Number.isFinite(date.getTime()) ? date.toISOString() : null;
};
const limitMessages: Record<CodexLimitReason, string> = {
  rate_limit_reached: 'Codex reports that a bucket rate limit has been reached.',
  workspace_owner_credits_depleted: 'Codex reports that workspace owner credits are depleted.',
  workspace_member_credits_depleted: 'Codex reports that workspace member credits are depleted.',
  workspace_owner_usage_limit_reached: 'Codex reports that the workspace owner usage limit has been reached.',
  workspace_member_usage_limit_reached: 'Codex reports that the workspace member usage limit has been reached.'
};

export function normalizeCodexRead(profile: UsageProfile, accountResult: unknown, limitResult: unknown, observedAt: Date): UsageAccount {
  const account = object(object(accountResult)?.account);
  const base: UsageAccount = {
    id: profile.id, label: profile.label, provider: 'codex-chatgpt', source: 'Codex app-server',
    plan: string(account?.planType, 80), email: isEmail(account?.email) ? account.email : null, observedAt: observedAt.toISOString(), state: 'ok', windows: [], resetCredits: null,
    ordinaryUsageAllowed: null, limitAccess: [], errors: []
  };
  if (!account || account.type !== 'chatgpt') {
    base.state = account ? 'unsupported' : 'unauthorized';
    base.errors.push({ code: base.state, message: account ? 'Profile is not signed in with ChatGPT.' : 'Profile is not signed in.' });
    return base;
  }
  const result = object(limitResult);
  const permission = result?.ordinaryUsageAllowed;
  base.ordinaryUsageAllowed = typeof permission === 'boolean' ? permission : null;
  const buckets = object(result?.rateLimitsByLimitId);
  const entries: Array<[string, unknown]> = buckets && Object.keys(buckets).length ? Object.entries(buckets) : [['codex', result?.rateLimits]];
  let incomplete = entries.length > 50 || (permission !== undefined && permission !== null && typeof permission !== 'boolean');
  let bucketBlocked = false;
  const addError = (code: string, message: string) => {
    if (base.errors.length < 20 && !base.errors.some((error) => error.code === code)) base.errors.push({ code, message });
  };
  if (permission === false) addError('ordinary_usage_denied', 'Codex reports that ordinary included usage is blocked; quota percentages and reset times do not override this permission.');
  const bucketIds = new Map<string, number>();
  for (const [key, raw] of entries.slice(0, 50)) {
    const bucket = object(raw);
    const id = bucket && (string(bucket.limitId) ?? string(key));
    if (id) bucketIds.set(id, (bucketIds.get(id) ?? 0) + 1);
  }
  const windowKeys = new Set<string>();
  for (const [key, raw] of entries.slice(0, 50)) {
    const bucket = object(raw);
    if (!bucket) { incomplete = true; continue; }
    const id = string(bucket.limitId) ?? string(key);
    if (!id) { incomplete = true; continue; }
    // Neither conflicting bucket is authoritative when the same ID appears more than once.
    if (bucketIds.get(id)! > 1) { incomplete = true; continue; }
    const label = string(bucket.limitName) ?? id;
    const rawReason = bucket.rateLimitReachedType;
    const reason = typeof rawReason === 'string' && CODEX_LIMIT_REASONS.includes(rawReason as CodexLimitReason) ? rawReason as CodexLimitReason : null;
    const rawSpendControl = bucket.spendControlReached;
    const spendControlReached = typeof rawSpendControl === 'boolean' ? rawSpendControl : null;
    if ((rawReason !== undefined && rawReason !== null && reason === null)
      || (rawSpendControl !== undefined && rawSpendControl !== null && spendControlReached === null)) incomplete = true;
    base.limitAccess!.push({ limitId: id, label, rateLimitReachedType: reason, spendControlReached });
    if (reason !== null) { bucketBlocked = true; addError(reason, limitMessages[reason]); }
    if (spendControlReached === true) {
      bucketBlocked = true;
      addError('spend_control_reached', 'Codex reports that a bucket spend-control limit has been reached.');
    }
    for (const [slot, rawWindow] of [['primary', bucket.primary], ['secondary', bucket.secondary]] as const) {
      const window = object(rawWindow);
      if (!window) continue;
      const used = number(window.usedPercent);
      const normalizedUsed = used !== null && used >= 0 && used <= 100 ? used : null;
      const duration = number(window.windowDurationMins);
      const item: UsageWindow = {
        limitId: id, label: `${label} · ${slot}`,
        kind: 'provider-reported-quota', usedPercent: normalizedUsed, usedKind: 'provider-reported-quota', remainingKind: 'calculated-estimate',
        remainingPercent: normalizedUsed === null ? null : Math.round((100 - normalizedUsed) * 10) / 10,
        durationMinutes: duration !== null && duration >= 0 && duration <= Number.MAX_SAFE_INTEGER ? duration : null, resetsAt: timestamp(window.resetsAt)
      };
      if (item.usedPercent === null || item.resetsAt === null || (duration !== null && item.durationMinutes === null)) incomplete = true;
      const windowKey = JSON.stringify([item.limitId, item.label]);
      if (windowKeys.has(windowKey)) { incomplete = true; continue; }
      windowKeys.add(windowKey);
      base.windows.push(item);
    }
  }
  const resetCredits = object(result?.rateLimitResetCredits);
  const availableCount = number(resetCredits?.availableCount);
  if (availableCount !== null && Number.isSafeInteger(availableCount) && availableCount >= 0) {
    const expiry = Array.isArray(resetCredits?.credits) ? resetCredits.credits.map((item) => timestamp(object(item)?.expiresAt)).filter((item): item is string => item !== null).sort()[0] ?? null : null;
    // Display details only; opaque credit IDs stay out of the status.
    const credits = Array.isArray(resetCredits?.credits) ? resetCredits.credits.slice(0, 20).map(object).filter((item) => item && (item.status === undefined || item.status === 'available')).map((item) => ({
      title: string(item!.title, 120), description: string(item!.description, 300), grantedAt: timestamp(item!.grantedAt), expiresAt: timestamp(item!.expiresAt),
    })) : undefined;
    base.resetCredits = { availableCount, earliestExpiry: expiry, ...(credits ? { credits } : {}) };
  }
  // Paid Codex credits are a count, not dollars.
  const paid = object(object(result?.rateLimits)?.credits) ?? entries.map(([, raw]) => object(object(raw)?.credits)).find(Boolean) ?? null;
  const paidBalance = typeof paid?.balance === 'string' && /^\d+(\.\d+)?$/.test(paid.balance) ? Number(paid.balance) : null;
  if (paid?.unlimited === true) base.balances = [{ kind: 'provider-reported-balance', currency: 'credits', amount: 0, label: 'Credits', note: 'Unlimited' }];
  else if (paidBalance !== null && (paid?.hasCredits !== false || paidBalance > 0)) base.balances = [{ kind: 'provider-reported-balance', currency: 'credits', amount: Math.round(paidBalance * 100) / 100, label: 'Credits' }];
  if (!base.windows.length) {
    base.state = 'partial';
    addError('missing_limits', 'Codex did not return a readable usage window.');
  }
  if (incomplete) {
    base.state = 'partial';
    addError('partial_limits', 'Some Codex quota or access values are unavailable or ambiguous; at most 50 buckets and 100 windows are retained.');
  }
  if (bucketBlocked) base.state = 'partial';
  if (permission === false) base.state = 'blocked';
  return base;
}

/** The available credit that expires first; credits without an expiry come last. */
export function nextResetCredit<T>(credits: unknown): (T & { id?: string }) | null {
  if (!Array.isArray(credits)) return null;
  const available = credits.map(object).filter((credit): credit is RecordValue => !!credit && (credit.status === undefined || credit.status === 'available'));
  const expiry = (credit: RecordValue) => typeof credit.expiresAt === 'number' ? credit.expiresAt : typeof credit.expiresAt === 'string' ? Date.parse(credit.expiresAt) / 1000 : Infinity;
  return (available.sort((a, b) => expiry(a) - expiry(b))[0] as (T & { id?: string }) | undefined) ?? null;
}

export type CodexResetOutcome = 'reset' | 'nothingToReset' | 'noCredit' | 'alreadyRedeemed';

/**
 * Redeems the next available banked reset through the documented app-server method
 * `account/rateLimitResetCredit/consume`. The backend picks the credit; the idempotency key
 * makes a retried request safe.
 */
export async function consumeCodexResetCredit(profile: UsageProfile, options: { codexBinary?: string; idempotencyKey: string; timeoutMs?: number }): Promise<CodexResetOutcome> {
  const home = resolve(profile.codexHome);
  if (!(await stat(home).then((info) => info.isDirectory(), () => false))) throw new Error('Codex profile directory is missing.');
  const env: NodeJS.ProcessEnv = { ...process.env, CODEX_HOME: home };
  delete env.OPENAI_API_KEY;
  delete env.CODEX_ACCESS_TOKEN;
  const child = spawn(options.codexBinary ?? 'codex', ['app-server', '--listen', 'stdio://'], { env, stdio: ['pipe', 'pipe', 'ignore'] });
  const lines = createInterface({ input: child.stdout, crlfDelay: Infinity });
  const waiting = new Map<number, (message: RecordValue) => void>();
  let nextId = 1;
  lines.on('line', (line) => {
    let message: RecordValue | null = null;
    try { message = object(JSON.parse(line)); } catch { return; }
    const id = message && message.method === undefined ? number(message.id) : null;
    if (id !== null) waiting.get(id)?.(message!);
  });
  const request = (method: string, params?: RecordValue) => new Promise<RecordValue>((resolveRequest, reject) => {
    const id = nextId++;
    waiting.set(id, resolveRequest);
    child.once('exit', () => reject(new Error('Codex app-server closed.')));
    child.stdin.write(`${JSON.stringify({ id, method, ...(params ? { params } : {}) })}\n`, (error) => { if (error) reject(new Error('Codex app-server closed.')); });
  });
  const timer = setTimeout(() => child.kill(), options.timeoutMs ?? 30_000);
  child.on('error', () => {});
  child.stdin.on('error', () => {});
  try {
    await request('initialize', { clientInfo: { name: 'subset_usage', title: 'Subset Usage', version: '0.0.0' } });
    child.stdin.write(`${JSON.stringify({ method: 'initialized', params: {} })}\n`);
    // Use the credit that expires first, the same one the dashboard names, instead of the backend's choice.
    const limits = await request('account/rateLimits/read');
    const creditId = nextResetCredit(object(object(limits.result)?.rateLimitResetCredits)?.credits)?.id ?? null;
    const response = await request('account/rateLimitResetCredit/consume', { idempotencyKey: options.idempotencyKey, ...(creditId ? { creditId } : {}) });
    const outcome = object(response.result)?.outcome;
    if (response.error !== undefined || !['reset', 'nothingToReset', 'noCredit', 'alreadyRedeemed'].includes(outcome as string)) throw new Error('Codex could not use a reset.');
    return outcome as CodexResetOutcome;
  } finally {
    clearTimeout(timer);
    lines.close();
    child.kill();
  }
}

export async function readCodexProfile(profile: UsageProfile, options: { codexBinary?: string; timeoutMs?: number } = {}): Promise<UsageAccount> {
  const empty = (code: UsageAccount['state'], message: string): UsageAccount => ({
    id: profile.id, label: profile.label, provider: 'codex-chatgpt', source: 'Codex app-server', plan: null,
    observedAt: null, state: code, windows: [], resetCredits: null, ordinaryUsageAllowed: null, limitAccess: [], errors: [{ code, message }]
  });
  if (!/^[a-zA-Z0-9_-]{1,64}$/.test(profile.id) || typeof profile.label !== 'string') return empty('unavailable', 'Invalid profile configuration.');
  const home = resolve(profile.codexHome);
  try { if (!(await stat(home)).isDirectory()) return empty('unavailable', 'Codex profile directory is missing.'); }
  catch { return empty('unavailable', 'Codex profile directory is missing.'); }

  const env: NodeJS.ProcessEnv = { ...process.env, CODEX_HOME: home };
  delete env.OPENAI_API_KEY;
  delete env.CODEX_ACCESS_TOKEN;
  const child = spawn(options.codexBinary ?? 'codex', ['app-server', '--listen', 'stdio://'], { env, stdio: ['pipe', 'pipe', 'ignore'] });
  const timeoutMs = options.timeoutMs ?? 15000;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let nextId = 1;
  const pending = new Map<number, { resolve: (value: unknown) => void; reject: (reason: Error) => void }>();
  let transportError: Error | undefined;
  const rejectResponses = (error: Error) => { for (const waiter of pending.values()) waiter.reject(error); pending.clear(); };
  const fail = (error: Error) => {
    transportError ??= error;
    rejectResponses(transportError);
  };
  child.on('error', fail);
  child.on('exit', () => fail(new Error('Codex app-server closed.')));
  child.stdin.on('error', fail);
  child.stdin.on('close', () => fail(new Error('Codex app-server closed.')));
  child.stdout.on('error', fail);
  child.stdout.on('end', () => fail(new Error('Codex app-server closed.')));
  const lines = createInterface({ input: child.stdout, crlfDelay: Infinity });
  lines.on('error', fail);
  lines.on('line', (line) => {
    if (line.length > 1024 * 1024) { fail(new Error('Codex response too large.')); child.kill(); return; }
    let message: RecordValue | null;
    try { message = object(JSON.parse(line)); }
    catch { rejectResponses(new Error('Codex app-server response malformed.')); return; }
    if (!message) { rejectResponses(new Error('Codex app-server response malformed.')); return; }
    // Server-initiated requests share the id field but are not responses to this client.
    const id = message.method === undefined ? number(message.id) : null;
    if (id === null) return;
    const waiter = pending.get(id);
    if (!waiter) return;
    pending.delete(id);
    if (message.error !== undefined) waiter.reject(new Error('Codex app-server request failed.'));
    else if (!Object.hasOwn(message, 'result')) waiter.reject(new Error('Codex app-server response malformed.'));
    else waiter.resolve(message.result);
  });
  const write = (message: RecordValue): Promise<void> => new Promise((resolveWrite, reject) => {
    if (!transportError && (child.stdin.destroyed || child.stdin.writableEnded)) fail(new Error('Codex app-server closed.'));
    if (transportError) { reject(transportError); return; }
    try {
      child.stdin.write(`${JSON.stringify(message)}\n`, (error) => {
        if (error) fail(error);
        if (transportError) reject(transportError);
        else resolveWrite();
      });
    } catch (error) {
      fail(error instanceof Error ? error : new Error('Codex app-server closed.'));
      reject(transportError);
    }
  });
  const request = (method: string, params?: RecordValue): Promise<unknown> => {
    if (transportError) return Promise.reject(transportError);
    const id = nextId++;
    const response = new Promise<unknown>((resolveRequest, reject) => {
      pending.set(id, { resolve: resolveRequest, reject });
    });
    return Promise.all([write({ id, method, ...(params ? { params } : {}) }), response]).then(([, result]) => result);
  };
  timer = setTimeout(() => { fail(new Error('Codex app-server timed out.')); child.kill(); }, timeoutMs);
  try {
    await request('initialize', { clientInfo: { name: 'subset_usage', title: 'Subset Usage', version: '0.0.0' } });
    await write({ method: 'initialized', params: {} });
    const account = await request('account/read', { refreshToken: false });
    if (object(object(account)?.account)?.type !== 'chatgpt') return normalizeCodexRead(profile, account, null, new Date());
    const limits = await request('account/rateLimits/read');
    return normalizeCodexRead(profile, account, limits, new Date());
  } catch (error) {
    const safe = error instanceof Error && /^Codex app-server (closed|request failed|timed out|response malformed)\.$/.test(error.message) ? error.message : 'Could not read Codex usage from this profile.';
    return empty('unavailable', safe);
  } finally {
    if (timer) clearTimeout(timer);
    lines.close();
    child.kill();
  }
}

import { spawn } from 'node:child_process';
import { stat } from 'node:fs/promises';
import { isAbsolute, resolve } from 'node:path';
import { isEmail, type UsageAccount } from './index.js';

const MAX_BYTES = 64 * 1024;
const safeName = (value: unknown): string | null => typeof value === 'string' && /^[A-Za-z0-9][A-Za-z0-9 ._()-]{0,63}$/.test(value) ? value : null;

/** Sign-in state reported by `claude auth status --json`. Organization IDs are discarded. */
export interface ClaudeAuthStatus {
  loggedIn: boolean;
  email: string | null;
  authMethod: string | null;
  subscriptionType: string | null;
  configDirectory: string | null;
}

export function normalizeClaudeAuthStatus(input: unknown): ClaudeAuthStatus | null {
  if (!input || typeof input !== 'object' || Array.isArray(input)) return null;
  const value = input as Record<string, unknown>;
  if (typeof value.loggedIn !== 'boolean') return null;
  const configDirectory = typeof value.configDirectory === 'string' && value.configDirectory.length <= 1024 && isAbsolute(value.configDirectory) ? resolve(value.configDirectory) : null;
  return { loggedIn: value.loggedIn, email: value.loggedIn && isEmail(value.email) ? value.email : null, authMethod: safeName(value.authMethod), subscriptionType: safeName(value.subscriptionType), configDirectory };
}

/**
 * Reads the documented Claude Code CLI sign-in status for one config directory.
 * The CLI owns credentials; Subset never reads them. A missing directory is not probed,
 * because the CLI creates the directory it is pointed at.
 */
export async function readClaudeAuthStatus(configDir: string, options: { claudeBinary?: string; timeoutMs?: number; defaultConfigDir?: string } = {}): Promise<ClaudeAuthStatus | null> {
  const directory = resolve(configDir);
  try { if (!(await stat(directory)).isDirectory()) return null; } catch { return null; }
  const env: NodeJS.ProcessEnv = { ...process.env };
  // Token variables would report their own account instead of the directory's stored sign-in.
  for (const key of ['ANTHROPIC_API_KEY', 'ANTHROPIC_AUTH_TOKEN', 'CLAUDE_CODE_OAUTH_TOKEN']) delete env[key];
  if (options.defaultConfigDir !== undefined && resolve(options.defaultConfigDir) === directory) delete env.CLAUDE_CONFIG_DIR;
  else env.CLAUDE_CONFIG_DIR = directory;
  return new Promise((resolveStatus) => {
    let output = '';
    let settled = false;
    const done = (value: ClaudeAuthStatus | null) => { if (!settled) { settled = true; clearTimeout(timer); child.kill(); resolveStatus(value); } };
    const child = spawn(options.claudeBinary ?? 'claude', ['auth', 'status', '--json'], { env, stdio: ['ignore', 'pipe', 'ignore'] });
    const timer = setTimeout(() => done(null), options.timeoutMs ?? 10_000);
    child.on('error', () => done(null));
    child.stdout.on('data', (chunk: Buffer) => {
      output += chunk.toString('utf8');
      if (output.length > MAX_BYTES) done(null);
    });
    child.on('close', () => {
      try { done(normalizeClaudeAuthStatus(JSON.parse(output))); } catch { done(null); }
    });
  });
}

/** Adds live sign-in state to a Claude Code quota snapshot account. */
export function withClaudeAuth(account: UsageAccount, auth: ClaudeAuthStatus | null): UsageAccount {
  if (!auth) return account;
  const next: UsageAccount = { ...account, plan: account.plan ?? auth.subscriptionType, ...(auth.email ? { email: auth.email } : {}), errors: [...account.errors] };
  if (!auth.loggedIn) {
    next.state = 'unauthorized';
    next.errors.unshift({ code: 'claude_signed_out', message: 'Claude Code is not signed in for this config directory. Run claude and use /login.' });
  } else if (auth.authMethod !== 'claude.ai') {
    next.state = 'unsupported';
    next.errors.unshift({ code: 'claude_not_subscription', message: 'This Claude Code config directory does not use a claude.ai subscription sign-in, so subscription quota is unavailable.' });
  } else if (account.observedAt === null) {
    // Signed in, but no collector has delivered quota yet; replace the generic read error.
    next.errors = [{ code: 'claude_awaiting_snapshot', message: 'Signed in to Claude Code. Quota appears after this account\'s status-line collector runs during a Claude Code session.' }];
  }
  return next;
}
import { createHash } from 'node:crypto';
import { userInfo } from 'node:os';
import { join, resolve } from 'node:path';
import type { UsageAccount, UsageWindow } from './index.js';
import { fetchJson, readKeychainSecret, readSmallFile, type SecretReader } from './local-auth.js';

/**
 * Live Claude subscription usage from the Claude Code sign-in stored for one config directory.
 * Opt-in only. It reads the stored OAuth access token, never the refresh token's endpoint:
 * Anthropic rotates refresh tokens, so refreshing here would sign the CLI out. Freshness is
 * left to `claude auth status`, which the host runs first. The usage endpoint is the one
 * Claude Code itself calls; it is not a documented public API and can change.
 */
const USAGE_URL = 'https://api.anthropic.com/api/oauth/usage';
const KEYCHAIN_SERVICE = 'Claude Code-credentials';

export interface ClaudeOAuthProfile { id: string; label: string; claudeConfigDir: string }

interface StoredClaude { accessToken: string; expiresAt: number | null; subscriptionType: string | null; rateLimitTier: string | null }

const object = (value: unknown): Record<string, unknown> | null => value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : null;
const percent = (value: unknown): number | null => typeof value === 'number' && Number.isFinite(value) ? Math.min(100, Math.max(0, Math.round(value * 10) / 10)) : null;
const isoTime = (value: unknown): string | null => {
  if (typeof value !== 'string' || value.length > 40) return null;
  const time = Date.parse(value);
  return Number.isFinite(time) ? new Date(time).toISOString() : null;
};

function parseStored(text: string | null): StoredClaude | null {
  if (!text) return null;
  let raw = text.trim();
  // Some keychain entries are stored hex-encoded.
  if (!raw.startsWith('{') && /^[0-9a-f]+$/i.test(raw) && raw.length % 2 === 0) raw = Buffer.from(raw, 'hex').toString('utf8');
  try {
    const oauth = object(object(JSON.parse(raw))?.claudeAiOauth);
    const accessToken = typeof oauth?.accessToken === 'string' && oauth.accessToken.length < 8192 ? oauth.accessToken : null;
    if (!accessToken) return null;
    return {
      accessToken,
      expiresAt: typeof oauth?.expiresAt === 'number' && Number.isFinite(oauth.expiresAt) ? oauth.expiresAt : null,
      subscriptionType: typeof oauth?.subscriptionType === 'string' && /^[a-z0-9_-]{1,40}$/i.test(oauth.subscriptionType) ? oauth.subscriptionType : null,
      rateLimitTier: typeof oauth?.rateLimitTier === 'string' && oauth.rateLimitTier.length <= 80 ? oauth.rateLimitTier : null,
    };
  } catch { return null; }
}

/** Turns a stored tier such as `default_claude_max_20x` into `Max 20x`. */
export function claudeTierName(value: unknown): string | null {
  if (typeof value !== 'string' || value.length > 80) return null;
  const match = /claude_(max|pro|team|enterprise)(?:_(\d+x))?/i.exec(value);
  if (!match) return null;
  const plan = `${match[1].charAt(0).toUpperCase()}${match[1].slice(1).toLowerCase()}`;
  return match[2] ? `${plan} ${match[2].toLowerCase()}` : plan;
}

/**
 * Plan label from the stored subscription type and rate-limit tier. The tier carries the usage
 * multiple (for example `default_claude_max_5x`) even for Team seats, so the subscription type
 * decides the plan: a Team seat with a multiple is a Premium seat.
 */
export function claudePlanName(subscriptionType: string | null, rateLimitTier: string | null): string | null {
  const multiple = rateLimitTier ? /_(\d+x)\b/i.exec(rateLimitTier)?.[1]?.toLowerCase() : undefined;
  const type = subscriptionType?.toLowerCase();
  if (type === 'team') return multiple ? `Team Premium ${multiple}` : 'Team';
  if (type === 'enterprise') return multiple ? `Enterprise ${multiple}` : 'Enterprise';
  if (type === 'max') return multiple ? `Max ${multiple}` : 'Max';
  if (type === 'pro') return 'Pro';
  return claudeTierName(rateLimitTier) ?? subscriptionType;
}

/** Claude Code names the keychain item for a custom config directory by the first 8 hex of its SHA-256. */
export function claudeKeychainService(configDir: string, isDefault: boolean): string {
  return isDefault ? KEYCHAIN_SERVICE : `${KEYCHAIN_SERVICE}-${createHash('sha256').update(configDir.normalize('NFC')).digest('hex').slice(0, 8)}`;
}

async function readStored(configDir: string, isDefault: boolean, readSecret: SecretReader): Promise<StoredClaude | null> {
  let account: string | undefined;
  try { account = userInfo().username; } catch { account = undefined; }
  // Try the spellings a user may have exported as CLAUDE_CONFIG_DIR.
  const spellings = isDefault ? [configDir] : [...new Set([configDir, `${configDir}/`, resolve(configDir)])];
  for (const spelling of spellings) {
    const service = claudeKeychainService(spelling, isDefault);
    const stored = parseStored(await readSecret(service, account)) ?? parseStored(account ? await readSecret(service) : null);
    if (stored) return stored;
  }
  return parseStored(await readSmallFile(join(configDir, '.credentials.json')));
}

export function normalizeClaudeOAuthUsage(profile: ClaudeOAuthProfile, input: unknown, observedAt: Date, plan: string | null = null): UsageAccount {
  const root = object(input);
  const windows: UsageWindow[] = [];
  const seen = new Set<string>();
  const push = (limitId: string, label: string, used: number | null, resetsAt: string | null, durationMinutes: number) => {
    if ((used === null && !resetsAt) || seen.has(limitId) || windows.length >= 20) return;
    seen.add(limitId);
    windows.push({
      limitId, label, kind: 'provider-reported-quota', usedPercent: used, usedKind: 'provider-reported-quota',
      remainingPercent: used === null ? null : Math.round((100 - used) * 10) / 10, remainingKind: 'calculated-estimate', durationMinutes, resetsAt,
    });
  };
  for (const [key, label, minutes] of [['five_hour', 'Five-hour quota', 300], ['seven_day', 'Seven-day quota', 10080]] as const) {
    const window = object(root?.[key]);
    if (window) push(key, label, percent(window.utilization), isoTime(window.resets_at), minutes);
  }
  // Per-model weekly limits arrive as weekly_scoped entries; older responses used seven_day_<model>.
  for (const entry of Array.isArray(root?.limits) ? root.limits.slice(0, 20) : []) {
    const scoped = object(entry);
    const name = object(object(scoped?.scope)?.model)?.display_name;
    if (scoped?.kind !== 'weekly_scoped' || typeof name !== 'string') continue;
    const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, '');
    if (!slug || slug.length > 24) continue;
    push(`seven_day_${slug}`, `Seven-day ${name.slice(0, 24)} quota`, percent(scoped.percent), isoTime(scoped.resets_at), 10080);
  }
  for (const model of ['fable', 'opus', 'sonnet', 'haiku']) {
    const window = object(root?.[`seven_day_${model}`]);
    if (window) push(`seven_day_${model}`, `Seven-day ${model} quota`, percent(window.utilization), isoTime(window.resets_at), 10080);
  }
  const incomplete = windows.some((window) => window.usedPercent === null || window.resetsAt === null);
  return {
    id: profile.id, label: profile.label, provider: 'claude-code', source: 'Claude usage (local sign-in)', plan,
    observedAt: observedAt.toISOString(), state: windows.length ? (incomplete ? 'partial' : 'ok') : 'partial', windows, resetCredits: null,
    errors: windows.length ? [] : [{ code: 'missing_quota', message: 'Claude returned no subscription usage windows for this sign-in.' }],
  };
}

export type ClaudeOAuthResult =
  | { kind: 'ok'; account: UsageAccount }
  | { kind: 'no-credential' }
  | { kind: 'error'; code: string; message: string; state: UsageAccount['state']; retryAfterMs?: number | null };

export async function readClaudeOAuthUsage(profile: ClaudeOAuthProfile, options: {
  isDefault: boolean; fetch?: typeof globalThis.fetch; readSecret?: SecretReader; now?: () => number;
}): Promise<ClaudeOAuthResult> {
  const stored = await readStored(resolve(profile.claudeConfigDir), options.isDefault, options.readSecret ?? readKeychainSecret);
  if (!stored) return { kind: 'no-credential' };
  const now = options.now?.() ?? Date.now();
  if (stored.expiresAt !== null && stored.expiresAt <= now) {
    return { kind: 'error', code: 'claude_token_expired', state: 'unauthorized', message: 'The local Claude Code sign-in has expired. Open Claude Code with this account to refresh it.' };
  }
  return fetchClaudeUsage(profile, stored.accessToken, { plan: claudePlanName(stored.subscriptionType, stored.rateLimitTier), fetch: options.fetch });
}

/** Reads Claude subscription usage with an access token another local tool already holds. */
export async function fetchClaudeUsage(profile: ClaudeOAuthProfile, accessToken: string, options: { plan?: string | null; fetch?: typeof globalThis.fetch; app?: string } = {}): Promise<ClaudeOAuthResult> {
  const app = options.app ?? 'Claude Code';
  try {
    const response = await fetchJson(USAGE_URL, { headers: {
      Authorization: `Bearer ${accessToken}`, Accept: 'application/json', 'anthropic-beta': 'oauth-2025-04-20', 'User-Agent': 'subset-usage/0.0.0',
    } }, { fetch: options.fetch });
    if (response.status === 401 || response.status === 403) return { kind: 'error', code: 'claude_unauthorized', state: 'unauthorized', message: `Claude rejected the local sign-in. Open ${app} with this account to sign in again.` };
    if (response.status === 429) return { kind: 'error', code: 'claude_rate_limited', state: 'unavailable', message: 'Claude is rate-limiting usage checks. Subset will try again in a few minutes.', retryAfterMs: response.retryAfterMs };
    if (response.status < 200 || response.status >= 300 || !object(response.json)) return { kind: 'error', code: 'claude_request_failed', state: 'unavailable', message: 'Could not read Claude usage for this sign-in.' };
    const account = normalizeClaudeOAuthUsage(profile, response.json, new Date(), options.plan ?? null);
    // Extra usage is paid usage beyond the plan, reported in cents.
    const extra = object(object(response.json)?.extra_usage);
    const usedCents = typeof extra?.used_credits === 'number' && Number.isFinite(extra.used_credits) && extra.used_credits >= 0 ? extra.used_credits : null;
    const limitCents = typeof extra?.monthly_limit === 'number' && Number.isFinite(extra.monthly_limit) && extra.monthly_limit > 0 ? extra.monthly_limit : null;
    if (extra && extra.is_enabled !== false && usedCents !== null) {
      account.spend = { kind: 'provider-reported-spend', currency: 'USD', label: 'Extra usage', used: usedCents / 100, limit: limitCents === null ? null : limitCents / 100, includedUsed: null, periodStart: null, periodEnd: null };
    }
    return { kind: 'ok', account };
  } catch {
    return { kind: 'error', code: 'claude_request_failed', state: 'unavailable', message: 'Could not read Claude usage for this sign-in.' };
  }
}

