    return normalizeCursorLocalUsage(profile, usage.json, credits?.status === 200 ? credits.json : null, new Date(), { plan, email: isEmail(email) ? email : null });
  } catch {
    return fail('cursor_request_failed', 'Could not read Cursor usage.');
  }
}

