    const credits = await fetchJson(`${API}/GetCreditGrantsBalance`, { method: 'POST', headers, body: '{}' }, { fetch: options.fetch }).catch(() => null);
    const planInfo = await fetchJson(`${API}/GetPlanInfo`, { method: 'POST', headers, body: '{}' }, { fetch: options.fetch }).catch(() => null);
    const planName = object(object(planInfo?.json)?.planInfo)?.planName;
    const membership = await readState('cursorAuth/stripeMembershipType');
    const email = await readState('cursorAuth/cachedEmail');
    const plan = typeof planName === 'string' && planName.length <= 40 ? planName : membership && /^[a-z_]{1,40}$/i.test(membership) ? membership : null;
    return normalizeCursorLocalUsage(profile, usage.json, credits?.status === 200 ? credits.json : null, new Date(), { plan, email: isEmail(email) ? email : null });
