import type { CursorProfile, UsageAccount } from './index.js';

const ENDPOINT = 'https://api.cursor.com/teams/spend';
const PAGE_SIZE = 100;
const MAX_PAGES = 20;
const MAX_PAGE_BYTES = 1024 * 1024;
const MAX_TOTAL_BYTES = 4 * MAX_PAGE_BYTES;
