    ['weekly', 'Weekly quota', 10080, ['weeklyQuotaRemainingPercent', 'weekly_quota_remaining_percent'], ['weeklyQuotaResetAtUnix', 'weekly_quota_reset_at_unix']],
  ] as const) {
