// Documented Claude Code windows, plus model-scoped weekly windows used only if the status line includes them.
const CLAUDE_WINDOWS: ReadonlyArray<readonly [string, string, number]> = [
  ['five_hour', 'Five-hour quota', 300],
  ['seven_day', 'Seven-day quota', 10080],
  ['seven_day_fable', 'Seven-day Fable quota', 10080],
  ['seven_day_opus', 'Seven-day Opus quota', 10080],
  ['seven_day_sonnet', 'Seven-day Sonnet quota', 10080],
  ['seven_day_haiku', 'Seven-day Haiku quota', 10080],
];
const secondsTime = (value: unknown): string | null => {
  const seconds = boundedNumber(value, MAX_SECONDS);
  return seconds === null ? null : new Date(seconds * 1000).toISOString();
};

// Antigravity names buckets `<group>-<span>`, such as `gemini-5h` or `3p-weekly`.
const ANTIGRAVITY_SPANS: Record<string, number> = { '5h': 300, hourly: 60, daily: 1440, '24h': 1440, weekly: 10080, '7d': 10080, monthly: 43200 };
export const antigravitySpan = (key: string): number | null => ANTIGRAVITY_SPANS[key.split('-').pop()?.toLowerCase() ?? ''] ?? null;

export function sanitizeSnapshot(profile: SnapshotProfile, input: unknown): unknown {
  const raw = object(input);
  const result: JsonObject = {};
  if (profile.provider === 'claude-code') {
    if (!has(raw, 'rate_limits')) return result;
    const limits = object(own(raw, 'rate_limits'));
    if (!limits) return { rate_limits: null };
    const clean: JsonObject = {};
    for (const [key] of CLAUDE_WINDOWS) {
      if (!has(limits, key)) continue;
      const window = object(own(limits, key));
      clean[key] = {
        used_percentage: boundedNumber(own(window, 'used_percentage'), 100),
        resets_at: boundedNumber(own(window, 'resets_at'), MAX_SECONDS)
      };
    }
    return { rate_limits: clean };
  }
  if (has(raw, 'plan_tier')) result.plan_tier = safeName(own(raw, 'plan_tier'));
  if (!has(raw, 'quota')) return result;
  const quota = object(own(raw, 'quota'));
  if (!quota) return { ...result, quota: null };
  const clean: JsonObject = {};
  let count = 0;
  for (const key of Object.keys(quota)) {
    if (!safeName(key)) continue;
    if (count++ >= MAX_WINDOWS) break;
    const bucket = object(own(quota, key));
    const item: JsonObject = { remaining_fraction: boundedNumber(own(bucket, 'remaining_fraction'), 1) };
    if (has(bucket, 'reset_time')) item.reset_time = isoTime(own(bucket, 'reset_time'));
    if (has(bucket, 'reset_in_seconds')) item.reset_in_seconds = boundedNumber(own(bucket, 'reset_in_seconds'), MAX_SECONDS);
    clean[key] = item;
  }
  result.quota = clean;
  return result;
}

function emptyAccount(profile: SnapshotProfile): UsageAccount {
  return {
    id: profile.id.slice(0, 64), label: profile.label.replace(/[\x00-\x1f\x7f]/g, '').slice(0, 128), provider: profile.provider,
    source: profile.provider === 'claude-code' ? 'Claude Code status-line snapshot' : 'Antigravity CLI status-line snapshot',
    plan: null, observedAt: null, state: 'unavailable', windows: [], resetCredits: null, errors: []
  };
}

function normalize(profile: SnapshotProfile, input: unknown, observedAt: Date): UsageAccount {
  const account = emptyAccount(profile);
  const time = observedAt.getTime();
  if (!Number.isFinite(time) || time < 0 || time > Date.now() || time > MAX_SECONDS * 1000) {
    account.errors.push({ code: 'invalid_observation', message: 'Snapshot observation time is invalid or in the future.' });
    return account;
  }
  account.observedAt = observedAt.toISOString();
  const data = object(sanitizeSnapshot(profile, input));
  let incomplete = false;
  if (profile.provider === 'claude-code') {
    const limits = object(own(data, 'rate_limits'));
    // Claude Code omits a window it has no data for and drops one once it resets; absence is not a partial read.
    for (const [key, label, duration] of CLAUDE_WINDOWS) {
      if (!has(limits, key)) continue;
      const raw = object(own(limits, key));
      const used = boundedNumber(own(raw, 'used_percentage'), 100);
      const resetsAt = secondsTime(own(raw, 'resets_at'));
      account.windows.push({
        limitId: key, label, kind: 'provider-reported-quota', usedPercent: used, usedKind: 'provider-reported-quota',
        remainingPercent: used === null ? null : 100 - used, remainingKind: 'calculated-estimate', durationMinutes: duration, resetsAt
      });
      if (used === null || resetsAt === null) incomplete = true;
    }
  } else {
    account.plan = safeName(own(data, 'plan_tier'));
    const quota = object(own(data, 'quota'));
    const entries = quota ? Object.entries(quota) : [];
    if (entries.length >= MAX_WINDOWS) incomplete = true;
    for (const [key, value] of entries) {
      const raw = object(value);
      const fraction = boundedNumber(own(raw, 'remaining_fraction'), 1);
      const remaining = fraction === null ? null : Math.round(fraction * 10000) / 100;
      let resetsAt = isoTime(own(raw, 'reset_time'));
      // An explicitly unavailable absolute reset must not be replaced by a countdown.
      if (!has(raw, 'reset_time')) {
        const seconds = boundedNumber(own(raw, 'reset_in_seconds'), MAX_SECONDS);
        if (seconds !== null) resetsAt = secondsTime(time / 1000 + seconds);
      }
      const window: UsageWindow = {
        limitId: key, label: key, kind: 'provider-reported-quota', usedPercent: remaining === null ? null : Math.round((100 - remaining) * 100) / 100,
        usedKind: 'calculated-estimate', remainingPercent: remaining, remainingKind: 'provider-reported-quota', durationMinutes: antigravitySpan(key), resetsAt
      };
      account.windows.push(window);
      if (remaining === null || resetsAt === null) incomplete = true;
    }
  }
  if (!account.windows.some((window) => window.usedPercent !== null || window.remainingPercent !== null)) {
    account.errors.push({ code: 'missing_quota', message: profile.provider === 'claude-code'
      ? 'Claude Code subscription quota is unavailable. Rate limits require Pro or Max and may be absent before the first API response.'
      : 'Antigravity did not supply a readable quota bucket.' });
  } else if (incomplete) {
    account.state = 'partial';
    account.errors.push({ code: 'partial_quota', message: 'Some quota windows or reset times are unavailable; at most 32 windows are retained.' });
  } else account.state = 'ok';
  return account;
}

export function normalizeClaudeSnapshot(profile: SnapshotProfile, input: unknown, observedAt: Date): UsageAccount {
  return normalize({ ...profile, provider: 'claude-code' }, input, observedAt);
}

export function normalizeAntigravitySnapshot(profile: SnapshotProfile, input: unknown, observedAt: Date): UsageAccount {
  return normalize({ ...profile, provider: 'antigravity' }, input, observedAt);
}

export function normalizeSnapshot(profile: SnapshotProfile, input: unknown, observedAt: Date): UsageAccount {
  return profile.provider === 'claude-code' ? normalizeClaudeSnapshot(profile, input, observedAt) : normalizeAntigravitySnapshot(profile, input, observedAt);
}

export async function readSnapshotProfile(profile: SnapshotProfile): Promise<UsageAccount> {
  const unavailable = (code: string, message: string) => {
    const account = emptyAccount(profile);
    account.errors.push({ code, message });
    return account;
  };
  let handle;
  try {
    // Nonblocking open and regular-file validation avoid hanging on special files.
    handle = await open(profile.snapshotFile, constants.O_RDONLY | constants.O_NONBLOCK);
    const info = await handle.stat();
    if (!info.isFile()) return unavailable('invalid_snapshot', 'Snapshot must be a regular JSON file.');
    if (info.size > MAX_BYTES) return unavailable('snapshot_too_large', 'Snapshot exceeds the 64 KiB size limit.');
    const buffer = Buffer.alloc(MAX_BYTES + 1);
    let length = 0;
    while (length < buffer.length) {
      const { bytesRead } = await handle.read(buffer, length, buffer.length - length, length);
      if (!bytesRead) break;
      length += bytesRead;
    }
    if (length > MAX_BYTES) return unavailable('snapshot_too_large', 'Snapshot exceeds the 64 KiB size limit.');
    let envelope: JsonObject | null;
    try { envelope = object(JSON.parse(buffer.toString('utf8', 0, length))); }
    catch { return unavailable('invalid_snapshot', 'Snapshot is not valid JSON.'); }
    if (!envelope || own(envelope, 'schemaVersion') !== 1 || own(envelope, 'provider') !== profile.provider || own(envelope, 'accountId') !== profile.id || !has(envelope, 'data')) {
      return unavailable('snapshot_mismatch', 'Snapshot version, provider, or account does not match this profile.');
    }
    const timestamp = isoTime(own(envelope, 'observedAt'));
    if (timestamp === null || Date.parse(timestamp) > Date.now()) return unavailable('invalid_observation', 'Snapshot observation time is invalid or in the future.');
    return normalizeSnapshot(profile, own(envelope, 'data'), new Date(timestamp));
  } catch {
    return unavailable('snapshot_read_failed', 'Could not read the configured snapshot file.');
  } finally {
    await handle?.close().catch(() => {});
  }
}
import type { UsageStatus, UsageWindow } from './index.js';

/**
 * Local usage history for trend views: observation time and used percentage per account window.
 * It stores no labels, plans, errors, or provider payloads. Hosts own persistence.
 */
export interface UsageHistory {
  schemaVersion: 1;
  /** accountId -> windowKey -> [observedAt epoch ms, used percent] in ascending time. */
  series: Record<string, Record<string, Array<[number, number]>>>;
}

export const HISTORY_MAX_AGE_MS = 8 * 24 * 60 * 60_000;
const MAX_POINTS = 2000;
const MIN_INTERVAL_MS = 4 * 60_000;
const MAX_ACCOUNTS = 20;
const MAX_WINDOWS = 100;

export const historyWindowKey = (window: Pick<UsageWindow, 'limitId' | 'label'>) => `${window.limitId}\u0000${window.label}`;
export const emptyUsageHistory = (): UsageHistory => ({ schemaVersion: 1, series: {} });

export function isUsageHistory(value: unknown): value is UsageHistory {
  const record = (item: unknown): item is Record<string, unknown> => !!item && typeof item === 'object' && !Array.isArray(item);
  if (!record(value) || value.schemaVersion !== 1 || !record(value.series)) return false;
  const accounts = Object.entries(value.series);
  if (accounts.length > MAX_ACCOUNTS) return false;
  return accounts.every(([id, windows]) => /^[a-zA-Z0-9_-]{1,64}$/.test(id) && record(windows) && Object.keys(windows).length <= MAX_WINDOWS
    && Object.entries(windows).every(([key, points]) => key.length <= 400 && Array.isArray(points) && points.length <= MAX_POINTS
      && points.every((point) => Array.isArray(point) && point.length === 2 && Number.isSafeInteger(point[0]) && point[0] >= 0
        && typeof point[1] === 'number' && Number.isFinite(point[1]) && point[1] >= 0 && point[1] <= 100)));
}

/**
 * Adds each account's newest observation. Repeated reads of the same observation are ignored, unchanged values
 * closer than four minutes apart are thinned, and points older than eight days or from removed accounts are dropped.
 */
export function recordUsageHistory(history: UsageHistory, status: UsageStatus, now = Date.now()): UsageHistory {
  const series: UsageHistory['series'] = {};
  const cutoff = now - HISTORY_MAX_AGE_MS;
  for (const account of status.accounts) {
    const previous = history.series[account.id] ?? {};
    const windows: Record<string, Array<[number, number]>> = {};
    const observed = account.observedAt ? Date.parse(account.observedAt) : NaN;
    for (const window of account.windows) {
      const key = historyWindowKey(window);
      const points = (previous[key] ?? []).filter(([time]) => time >= cutoff && time <= now);
      if (Number.isFinite(observed) && observed >= cutoff && observed <= now && window.usedPercent !== null) {
        const last = points.at(-1);
        const used = Math.round(window.usedPercent * 100) / 100;
        if (!last || (observed > last[0] && (used !== last[1] || observed - last[0] >= MIN_INTERVAL_MS))) points.push([observed, used]);
      }
      if (points.length) windows[key] = points.slice(-MAX_POINTS);
    }
    if (Object.keys(windows).length) series[account.id] = windows;
  }
  return { schemaVersion: 1, series };
}
import { execFile } from 'node:child_process';
import { isEmail, type UsageAccount } from './index.js';

/**
 * Amp credit balance from the documented `amp usage` command. The Amp CLI owns its sign-in;
 * another saved account can be read by naming an environment variable holding that account's
 * AMP_API_KEY. The CLI prints text, so parsing is limited to the signed-in email and dollar amounts.
 */
export interface AmpProfile { id: string; label: string; provider: 'amp'; credentialEnv?: string }

const money = (value: string | undefined): number | null => {
  if (!value) return null;
  const amount = Number(value.replace(/,/g, ''));
  return Number.isFinite(amount) && amount >= 0 ? Math.round(amount * 100) / 100 : null;
};

export function normalizeAmpUsage(profile: AmpProfile, output: string, observedAt: Date): UsageAccount {
  const text = output.slice(0, 16_384);
  const email = /Signed in as\s+(\S+@\S+?)[\s(]/.exec(`${text} `)?.[1];
  const credits = money(/credits:?\**\s*\$([\d,]+(?:\.\d+)?)\s+remaining/i.exec(text)?.[1]);
  const free = money(/\$([\d,]+(?:\.\d+)?)\s+Amp Free remaining today/i.exec(text)?.[1]);
  const balances: NonNullable<UsageAccount['balances']> = [];
  if (credits !== null) balances.push({ kind: 'provider-reported-balance', currency: 'USD', amount: credits, label: 'Credits remaining', ...(free !== null ? { note: 'Includes Amp Free' } : {}) });
  if (free !== null) balances.push({ kind: 'provider-reported-balance', currency: 'USD', amount: free, label: 'Amp Free left today', note: 'Resets daily' });
  return {
    id: profile.id, label: profile.label, provider: 'amp', source: 'amp usage', plan: null, email: isEmail(email) ? email : null,
    observedAt: observedAt.toISOString(), state: balances.length ? 'ok' : 'partial', windows: [], resetCredits: null, balances,
    errors: balances.length ? [] : [{ code: 'amp_unreadable', message: 'amp usage did not report a credit balance this dashboard can read.' }],
  };
}

export function readAmpProfile(profile: AmpProfile, options: { ampBinary?: string; env?: NodeJS.ProcessEnv; timeoutMs?: number } = {}): Promise<UsageAccount> {
  const fail = (code: string, message: string, state: UsageAccount['state'] = 'unavailable'): UsageAccount => ({
    id: profile.id, label: profile.label, provider: 'amp', source: 'amp usage', plan: null, observedAt: null, state, windows: [], resetCredits: null, errors: [{ code, message }],
  });
  const base = options.env ?? process.env;
  const env: NodeJS.ProcessEnv = { ...base };
  if (profile.credentialEnv) {
    const key = Object.hasOwn(base, profile.credentialEnv) ? base[profile.credentialEnv] : undefined;
    if (!key) return Promise.resolve(fail('amp_missing_key', 'The configured Amp API key variable is not set for the usage server.', 'unauthorized'));
    env.AMP_API_KEY = key;
  }
  return new Promise((resolve) => {
    execFile(options.ampBinary ?? 'amp', ['usage'], { env, encoding: 'utf8', timeout: options.timeoutMs ?? 20_000, maxBuffer: 64 * 1024, killSignal: 'SIGKILL' }, (error, stdout) => {
      if (error) {
        // Never surface CLI output: it can include account details.
        resolve((error as NodeJS.ErrnoException).code === 'ENOENT'
          ? fail('amp_missing_cli', 'The amp CLI is not installed for the usage server.')
          : /not (signed|logged) in|login/i.test(String(stdout)) ? fail('amp_signed_out', 'Amp is not signed in. Run amp login.', 'unauthorized')
            : fail('amp_failed', 'amp usage did not finish successfully.'));
        return;
      }
      resolve(normalizeAmpUsage(profile, stdout, new Date()));
    });
  });
}
<script lang="ts">
  import { onMount } from 'svelte';
  import * as echarts from 'echarts/core';
  import { LineChart } from 'echarts/charts';
  import { GridComponent, MarkLineComponent, TooltipComponent } from 'echarts/components';
  import { historyResets } from './present.js';
  import { SVGRenderer } from 'echarts/renderers';

  echarts.use([LineChart, GridComponent, MarkLineComponent, TooltipComponent, SVGRenderer]);

  interface Props {
    series: Array<{ name: string; points: Array<[number, number]> }>;
    label: string;
    /** True when points are remaining percentages, so a reset is a rise. */
    remainingMode?: boolean;
  }
  let { series, label, remainingMode = false }: Props = $props();

  let element: HTMLDivElement | undefined = $state();
  let chart: echarts.ECharts | undefined;
  let theme = $state(0);

  const palette = (node: HTMLElement) => {
    const style = getComputedStyle(node);
    const read = (name: string, fallback: string) => style.getPropertyValue(name).trim() || fallback;
    return {
      text: read('--text-3', '#8a8d91'), line: read('--line', '#e3e1d9'), surface: read('--surface', '#fff'), ink: read('--text', '#17181a'),
      lines: [read('--accent', '#4b3ff2'), read('--trend-2', '#d6862f'), read('--trend-3', '#2f9e8f'), read('--trend-4', '#a04fd6')],
    };
  };
  const time = new Intl.DateTimeFormat(undefined, { weekday: 'short', hour: 'numeric', minute: '2-digit' });

  // A reset is a sharp drop in usage, or a sharp rise when the series shows remaining.
  const resets = $derived([...new Set(series.flatMap((item) => {
    const falling = historyResets(item.points);
    const rising = historyResets(item.points.map(([time, value]): [number, number] => [time, 100 - value]));
    return remainingMode ? rising : falling;
  }))].sort((a, b) => a - b));

  function render() {
    if (!element) return;
    chart ??= echarts.init(element, undefined, { renderer: 'svg' });
    const colors = palette(element);
    chart.setOption({
      animation: false,
      color: colors.lines,
      grid: { left: 30, right: 6, top: 8, bottom: 20 },
      tooltip: {
        trigger: 'axis', backgroundColor: colors.surface, borderColor: colors.line, textStyle: { color: colors.ink, fontSize: 12 },
        valueFormatter: (value: unknown) => typeof value === 'number' ? `${value}%` : String(value),
        axisPointer: { lineStyle: { color: colors.line } },
      },
      xAxis: {
        type: 'time', axisLine: { lineStyle: { color: colors.line } }, axisTick: { show: false },
        axisLabel: { color: colors.text, fontSize: 10, hideOverlap: true, formatter: { day: '{ee}', hour: '{HH}:{mm}' } },
        splitLine: { show: false },
      },
      yAxis: {
        type: 'value', min: 0, max: 100, interval: 50,
        axisLabel: { color: colors.text, fontSize: 10, formatter: '{value}%' },
        splitLine: { lineStyle: { color: colors.line, type: 'dashed' } },
      },
      series: series.map((item, index) => ({
        name: item.name, type: 'line', data: item.points, showSymbol: item.points.length < 3, symbolSize: 4,
        lineStyle: { width: 1.6 }, areaStyle: series.length === 1 ? { opacity: 0.08 } : undefined, step: false,
        // Resets show as dashed vertical lines where a window's usage dropped.
        ...(index === 0 && resets.length ? { markLine: {
          silent: true, symbol: 'none', animation: false,
          lineStyle: { color: colors.text, type: 'dashed', width: 1 },
          label: { show: true, position: 'insideEndTop', formatter: 'Reset', color: colors.text, fontSize: 9 },
          data: resets.map((time) => ({ xAxis: time })),
        } } : {}),
      })),
    }, true);
    chart.resize();
  }

  onMount(() => {
    const media = window.matchMedia('(prefers-color-scheme: dark)');
    const onTheme = () => { theme++; };
    media.addEventListener('change', onTheme);
    // Hosts can override the system theme with html[data-theme].
    const themeObserver = new MutationObserver(onTheme);
    themeObserver.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });
    const observer = new ResizeObserver(() => chart?.resize());
    if (element) observer.observe(element);
    return () => { media.removeEventListener('change', onTheme); themeObserver.disconnect(); observer.disconnect(); chart?.dispose(); chart = undefined; };
  });

  $effect(() => {
    void theme;
    void series;
    render();
  });

  const summary = $derived(series.map((item) => {
    const last = item.points.at(-1);
    return last ? `${item.name} ${last[1]}% at ${time.format(last[0])}` : item.name;
  }).join('; '));
</script>

<figure class="trend">
  <div bind:this={element} class="canvas" role="img" aria-label={`${label}. Latest: ${summary}.`}></div>
  {#if series.length > 1}
    <figcaption>
      {#each series as item, index (item.name)}<span><i class={`line-${index}`}></i>{item.name}</span>{/each}
