      series: series.map((item, index) => ({
        name: item.name, type: 'line', data: item.points, showSymbol: item.points.length < 3, symbolSize: 4,
        lineStyle: { width: 1.6 }, areaStyle: series.length === 1 ? { opacity: 0.08 } : undefined, step: false,
        // Resets show as dashed vertical lines where a window's usage dropped.
        ...(index === 0 && resets.length ? { markLine: {
          silent: true, symbol: 'none', animation: false,
          lineStyle: { color: colors.text, type: 'dashed', width: 1 },
          label: { show: true, position: 'insideEndTop', formatter: 'Reset', color: colors.text, fontSize: 9 },
          data: resets.map((time) => ({ xAxis: time })),
        } } : {}),
      })),
    }, true);
    chart.resize();
  }

  onMount(() => {
    const media = window.matchMedia('(prefers-color-scheme: dark)');
    const onTheme = () => { theme++; };
    media.addEventListener('change', onTheme);
    // Hosts can override the system theme with html[data-theme].
    const themeObserver = new MutationObserver(onTheme);
    themeObserver.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });
    const observer = new ResizeObserver(() => chart?.resize());
    if (element) observer.observe(element);
    return () => { media.removeEventListener('change', onTheme); themeObserver.disconnect(); observer.disconnect(); chart?.dispose(); chart = undefined; };
  });

  $effect(() => {
    void theme;
    void series;
    render();
  });

  const summary = $derived(series.map((item) => {
    const last = item.points.at(-1);
    return last ? `${item.name} ${last[1]}% at ${time.format(last[0])}` : item.name;
  }).join('; '));
</script>

<figure class="trend">
  <div bind:this={element} class="canvas" role="img" aria-label={`${label}. Latest: ${summary}.`}></div>
  {#if series.length > 1}
    <figcaption>
      {#each series as item, index (item.name)}<span><i class={`line-${index}`}></i>{item.name}</span>{/each}
    </figcaption>
  {/if}
</figure>

<style>
  .trend { margin: 0; }
  .canvas { width: 100%; height: 104px; }
  figcaption { display: flex; flex-wrap: wrap; gap: 4px 12px; font-size: .74rem; color: var(--text-3); margin-top: 4px; }
  figcaption span { display: inline-flex; align-items: center; gap: 5px; }
  figcaption i { width: 10px; height: 2px; border-radius: 1px; background: var(--accent); }
  figcaption i.line-1 { background: var(--trend-2); }
  figcaption i.line-2 { background: var(--trend-3); }
  figcaption i.line-3 { background: var(--trend-4); }
</style>
<script lang="ts" module>
  let instance = 0;
</script>

<script lang="ts">
  import PiIcon from 'phosphor-svelte/lib/PiIcon';
  import RobotIcon from 'phosphor-svelte/lib/RobotIcon';
  import type { UsageProvider } from './index.js';
  import { providerLogos } from './provider-logos.js';

  /** `bare` renders only the logo, without the tile. */
  let { provider, size = 38, bare = false }: { provider: UsageProvider; size?: number; bare?: boolean } = $props();

  // Inline SVG IDs are document-global, so each rendered logo gets its own.
  const suffix = `-p${++instance}`;
  const logo = $derived(providerLogos[provider]);
  const body = $derived(logo ? logo.body.replace(/\bid="([^"]+)"/g, `id="$1${suffix}"`).replace(/url\(#([^)]+)\)/g, `url(#$1${suffix})`).replace(/href="#([^"]+)"/g, `href="#$1${suffix}"`) : '');
</script>

<span class="provider-icon" class:bare class:full={logo?.fullBleed && !bare} style={`--size:${size}px`} aria-hidden="true">
  {#if logo}
    {@const scale = bare || logo.fullBleed ? 1 : 0.52}
    <svg viewBox={logo.viewBox} width={Math.round(size * scale)} height={Math.round(size * scale)} focusable="false">{@html body}</svg>
  {:else}
    {#if provider === 'pi'}<PiIcon size={Math.round(size * (bare ? 1 : 0.55))} weight="bold" />{:else}<RobotIcon size={Math.round(size * (bare ? 1 : 0.55))} weight="bold" />{/if}
  {/if}
</span>

<style>
  .provider-icon { flex: none; width: var(--size); height: var(--size); border-radius: calc(var(--size) * .27); display: grid; place-items: center; border: 1px solid var(--line, #e3e1d9); background: var(--surface-2, #f0efe9); color: var(--text, #17181a); }
  .full { overflow: hidden; border-color: transparent; }
  .bare.full svg, .bare svg { border-radius: 3px; }
  .bare { width: auto; height: auto; border: 0; border-radius: 0; background: none; }
  svg { display: block; }
</style>
// Regenerates packages/usage/src/provider-logos.ts from the CC0 Iconify "logos" set (gilbarbara/logos).
// Only the provider marks the view uses are copied, so the full icon set is never bundled.
import { readFile, writeFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';

const require = createRequire(new URL('../packages/usage/package.json', import.meta.url));
const { icons } = require('@iconify-json/logos');
const { getIconData, iconToSVG } = require('@iconify/utils');

// Near-black marks follow the text color so they stay visible in dark mode.
const marks = {
  'codex-chatgpt': ['openai-icon', true], 'claude-code': ['claude-icon', false], antigravity: ['antigravity', false], cursor: ['cursor-icon', true], 'cursor-local': ['cursor-icon', true],
  devin: ['devin', true], opencode: ['opencode-icon', true],
};
const entries = Object.entries(marks).map(([provider, [name, mono]]) => {
  const data = getIconData(icons, name);
  if (!data) throw new Error(`Missing icon ${name}`);
  const svg = iconToSVG(data);
  let body = svg.body.replace(/fill="#(?:000|000000|26251e|211e1e|131010|0a0a0a|1a1a1a)"/gi, 'fill="currentColor"');
  // Element IDs (gradients, masks) are made unique per rendered instance by ProviderIcon.
  if (mono && !/fill=/.test(body)) body = `<g fill="currentColor">${body}</g>`;
  return `  '${provider}': { icon: 'logos:${name}', viewBox: '${svg.attributes.viewBox}', body: ${JSON.stringify(body)} },`;
});

// Marks not in the Iconify set are vendored as reviewed, script-free SVG files in scripts/logos.
for (const [provider, file] of [['factory-droid', 'factory-droid.svg'], ['amp', 'amp.svg'], ['pi', 'pi.svg'], ['omp', 'omp.svg'], ['hermes', 'hermes.svg']]) {
  const svg = await readFile(new URL(`./logos/${file}`, import.meta.url), 'utf8');
  if (/<script|\son[a-z]+=|<foreignObject|<image|href="http/i.test(svg)) throw new Error(`${file} contains active or external content.`);
  const viewBox = /viewBox="([^"]+)"/.exec(svg)?.[1];
  const body = /<svg[^>]*>([\s\S]*)<\/svg>/.exec(svg)?.[1]?.trim();
  if (!viewBox || !body) throw new Error(`${file} is not a single SVG.`);
  // App icons with their own background fill the tile instead of sitting inside it.
  const fullBleed = provider === 'amp' || provider === 'omp' ? ', fullBleed: true' : '';
  entries.push(`  '${provider}': { icon: 'vendored:${file}', viewBox: '${viewBox}', body: ${JSON.stringify(body)}${fullBleed} },`);
}

const output = `// Generated by scripts/generate-provider-logos.mjs from @iconify-json/logos ${require('@iconify-json/logos/package.json').version}.
// Icons: gilbarbara/logos, CC0-1.0; Factory, Amp, Pi, omp, and Hermes marks from their sites (scripts/logos). Do not edit by hand.
export const providerLogos: Record<string, { icon: string; viewBox: string; body: string; fullBleed?: boolean }> = {
${entries.join('\n')}
};
`;
await writeFile(fileURLToPath(new URL('../packages/usage/src/provider-logos.ts', import.meta.url)), output);

