    31	export async function readClaudeAuthStatus(configDir: string, options: { claudeBinary?: string; timeoutMs?: number; defaultConfigDir?: string } = {}): Promise<ClaudeAuthStatus | null> {
    32	  const directory = resolve(configDir);
    33	  try { if (!(await stat(directory)).isDirectory()) return null; } catch { return null; }
    34	  const env: NodeJS.ProcessEnv = { ...process.env };
    35	  // Token variables would report their own account instead of the directory's stored sign-in.
    36	  for (const key of ['ANTHROPIC_API_KEY', 'ANTHROPIC_AUTH_TOKEN', 'CLAUDE_CODE_OAUTH_TOKEN']) delete env[key];
    37	  if (options.defaultConfigDir !== undefined && resolve(options.defaultConfigDir) === directory) delete env.CLAUDE_CONFIG_DIR;
    38	  else env.CLAUDE_CONFIG_DIR = directory;
    39	  return new Promise((resolveStatus) => {
    40	    let output = '';
    41	    let settled = false;
    42	    const done = (value: ClaudeAuthStatus | null) => { if (!settled) { settled = true; clearTimeout(timer); child.kill(); resolveStatus(value); } };
    43	    const child = spawn(options.claudeBinary ?? 'claude', ['auth', 'status', '--json'], { env, stdio: ['ignore', 'pipe', 'ignore'] });
    44	    const timer = setTimeout(() => done(null), options.timeoutMs ?? 10_000);
    45	    child.on('error', () => done(null));
    46	    child.stdout.on('data', (chunk: Buffer) => {
    47	      output += chunk.toString('utf8');
    48	      if (output.length > MAX_BYTES) done(null);
    49	    });
    54	// result, and after a 429 keep showing the last values (with their original observation time) until
    55	// the provider's Retry-After, or five minutes, has passed.
    56	const liveCache = new Map();
    57	async function throttled(key, minIntervalMs, read) {
    58	  const now = Date.now();
    59	  const entry = liveCache.get(key);
    60	  if (entry?.account && now - entry.at < minIntervalMs) return entry.account;
    61	  if (entry?.cooldownUntil > now) return entry.account ?? entry.error;
    62	  const result = await read();
    63	  const limited = result.errors?.some((error) => /rate_limited$/.test(error.code));
    64	  if (limited) {
    65	    liveCache.set(key, { ...entry, error: result, cooldownUntil: now + (result.retryAfterMs ?? 5 * 60_000) });
    66	    return entry?.account ?? result;
    67	  }
    68	  if (result.observedAt && ['ok', 'partial'].includes(result.state)) liveCache.set(key, { account: result, at: now });
    69	  else liveCache.delete(key);
