    33	/**
    34	 * Adds each account's newest observation. Repeated reads of the same observation are ignored, unchanged values
    35	 * closer than four minutes apart are thinned, and points older than eight days or from removed accounts are dropped.
    36	 */
    37	export function recordUsageHistory(history: UsageHistory, status: UsageStatus, now = Date.now()): UsageHistory {
    38	  const series: UsageHistory['series'] = {};
    39	  const cutoff = now - HISTORY_MAX_AGE_MS;
    40	  for (const account of status.accounts) {
    41	    const previous = history.series[account.id] ?? {};
    42	    const windows: Record<string, Array<[number, number]>> = {};
    43	    const observed = account.observedAt ? Date.parse(account.observedAt) : NaN;
    44	    for (const window of account.windows) {
    45	      const key = historyWindowKey(window);
    46	      const points = (previous[key] ?? []).filter(([time]) => time >= cutoff && time <= now);
    47	      if (Number.isFinite(observed) && observed >= cutoff && observed <= now && window.usedPercent !== null) {
    48	        const last = points.at(-1);
    49	        const used = Math.round(window.usedPercent * 100) / 100;
    50	        if (!last || (observed > last[0] && (used !== last[1] || observed - last[0] >= MIN_INTERVAL_MS))) points.push([observed, used]);
    51	      }
    52	      if (points.length) windows[key] = points.slice(-MAX_POINTS);
    53	    }
    54	    if (Object.keys(windows).length) series[account.id] = windows;
    55	  }
    56	  return { schemaVersion: 1, series };
    57	}
