// Bundles the CLI with the private @subset/usage package inlined, and copies the built
// dashboard from apps/usage/dist into web/. The published package has no runtime dependencies.
import { cp, mkdir, readFile, rm, stat } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { build } from 'rolldown';

const root = fileURLToPath(new URL('..', import.meta.url));
const webSource = fileURLToPath(new URL('../../../apps/usage/dist/', import.meta.url));
const exists = (path) => stat(path).then(() => true, () => false);

if (process.argv.includes('--check')) {
  // prepack: refuse to pack without both halves.
  for (const file of ['dist/cli.mjs', 'web/index.html']) {
    if (!(await exists(`${root}${file}`))) { console.error(`Missing ${file}. Run npm run build at the repository root first.`); process.exit(1); }
  }
  const head = (await readFile(`${root}dist/cli.mjs`, 'utf8')).slice(0, 40);
  if (!head.startsWith('#!/usr/bin/env node')) { console.error('dist/cli.mjs has no shebang.'); process.exit(1); }
  process.exit(0);
}

await rm(`${root}dist`, { recursive: true, force: true });
await build({
  input: `${root}src/server.mjs`,
  platform: 'node',
  external: [/^node:/],
  output: { file: `${root}dist/cli.mjs`, format: 'esm', banner: '#!/usr/bin/env node' },
});
if (!(await exists(`${webSource}index.html`))) { console.error('apps/usage/dist is missing. Build @subset/usage-web first.'); process.exit(1); }
await rm(`${root}web`, { recursive: true, force: true });
await mkdir(`${root}web`, { recursive: true });
await cp(webSource, `${root}web`, { recursive: true });
name: Publish tagged package

# Push a tag like usage-v0.1.0 (slug from release-packages.json, version matching the
# package.json) to build, test, and publish that one package to npm.
on:
  push:
    tags:
      - '*-v*.*.*'
  workflow_dispatch:
    inputs:
      release_tag:
        description: 'Release tag in the form <package-slug>-v<version>'
        required: true
        type: string

permissions:
  contents: read

concurrency:
  group: publish-${{ github.ref }}
  cancel-in-progress: false

jobs:
  publish:
    runs-on: ubuntu-latest
    env:
      RELEASE_TAG: ${{ github.event_name == 'workflow_dispatch' && inputs.release_tag || github.ref_name }}

    steps:
      - name: Checkout
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: 22
          registry-url: https://registry.npmjs.org
          cache: npm

      - name: Resolve publish target
        id: resolve
        run: node ./scripts/resolve-release-tag.mjs "${RELEASE_TAG}"

      # Published packages bundle private workspaces (for example the CLI bundles
      # @subset/usage and the built dashboard), so install and build from the root.
      - name: Install workspace dependencies
        run: npm ci

      - name: Check workspaces
        run: npm run check

      - name: Build workspaces
        run: npm run build

      - name: Test package
        run: npm test --workspace=${{ steps.resolve.outputs.pkg_name }}

      - name: Pack package
        working-directory: ${{ steps.resolve.outputs.pkg_path }}
        run: npm pack --json

      - name: Publish package
        working-directory: ${{ steps.resolve.outputs.pkg_path }}
        run: npm publish --access public
        env:
          NODE_AUTH_TOKEN: ${{ secrets.NPM_TOKEN }}
// Resolves a <slug>-v<version> release tag to one publishable workspace (modelled on the
// Superfunctions publish-tag workflow). Fails unless name, version, and public status match.
import { appendFile, readFile } from 'node:fs/promises';
import path from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const repoRoot = path.resolve(__dirname, '..');
const releasePackagesPath = path.join(repoRoot, 'release-packages.json');
const tagPattern = /^(?<slug>[a-z0-9][a-z0-9-]*)-v(?<version>\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?)$/;

function fail(message) {
  console.error(message);
  process.exit(1);
}

async function loadReleaseTargets() {
  const raw = await readFile(releasePackagesPath, 'utf8');
  const releasePackages = JSON.parse(raw);

  if (!Array.isArray(releasePackages)) {
    fail(`Expected ${path.relative(repoRoot, releasePackagesPath)} to contain an array`);
  }

  const targets = [];

  for (const entry of releasePackages) {
    if (!entry?.slug || !entry?.path || !entry?.name) {
      fail(`Invalid release target entry in ${path.relative(repoRoot, releasePackagesPath)}: ${JSON.stringify(entry)}`);
    }

    targets.push({
      slug: entry.slug,
      name: entry.name,
      path: entry.path,
    });
  }

  return targets;
}

async function writeOutputs(outputs) {
  if (!process.env.GITHUB_OUTPUT) {
    return;
  }

  const lines = Object.entries(outputs).map(([key, value]) => `${key}=${value}`);
  await appendFile(process.env.GITHUB_OUTPUT, `${lines.join('\n')}\n`);
}

const tag = process.argv[2] ?? process.env.GITHUB_REF_NAME;

if (!tag) {
  fail('Expected a release tag argument or GITHUB_REF_NAME');
}

const match = tag.match(tagPattern);

if (!match?.groups) {
  fail(`Unsupported tag format: ${tag}. Expected <package-slug>-v<version>.`);
}

const { slug, version } = match.groups;
const releaseTargets = await loadReleaseTargets();
const target = releaseTargets.find((candidate) => candidate.slug === slug);

if (!target) {
  const supportedSlugs = releaseTargets.map((target) => target.slug).join(', ');
  fail(`No publishable workspace found for slug "${slug}". Supported slugs: ${supportedSlugs}`);
}

const packageJsonFile = path.join(repoRoot, target.path, 'package.json');
const packageJson = JSON.parse(await readFile(packageJsonFile, 'utf8'));

if (packageJson.name !== target.name) {
  fail(
    `Release target ${target.slug} expected ${target.name} at ${target.path}/package.json, found ${packageJson.name ?? 'undefined'}`,
  );
}

if (packageJson.private !== false) {
  fail(`${target.name} at ${target.path} is not marked private: false, so it is not ready to publish`);
}

if (packageJson.version !== version) {
  fail(`Tag version ${version} does not match ${target.name}@${packageJson.version} in ${target.path}/package.json`);
}

await writeOutputs({
  pkg_slug: target.slug,
  pkg_name: target.name,
  pkg_version: packageJson.version,
  pkg_path: target.path,
});

console.log(
  JSON.stringify(
    {
      tag,
      slug: target.slug,
      name: target.name,
      version: packageJson.version,
      path: target.path,
    },
    null,
    2,
  ),
);
