      const auth = await readClaudeAuthStatus(profile.claudeConfigDir);
      const snapshot = await readSnapshotProfile(profile);
      const fallback = withClaudeAuth(snapshot, auth);
      if (!localCredentials || auth?.loggedIn === false) return fallback;
      const live = await throttled(`claude:${profile.id}:${auth?.email ?? ''}`, 300_000, async () => {
        const result = await readClaudeOAuthUsage(profile, { isDefault: profile.claudeConfigDir === resolve(homedir(), '.claude') });
