  }
  const groups = new Map();
  for (const profile of configured.filter(isHarnessLogin)) {
    const email = emails.get(profile.id);
    const key = email ? `${profile.login === 'chatgpt' ? 'codex-chatgpt' : 'claude-code'}|${email.toLowerCase()}` : `profile|${profile.id}`;
    groups.set(key, [...(groups.get(key) ?? []), profile]);
