        if (connectionMatch && request.method === 'GET') { json(response, 200, accounts.connection(connectionMatch[1])); return; }
        const cancelMatch = path.match(/^\/api\/connections\/([a-zA-Z0-9_-]{1,64})\/cancel$/);
