async function readEntries(tool: StoredLoginTool, dataDir?: string): Promise<StoredEntry[]> {
  if (tool === 'omp') {
    return (await readOmpRows(storedLoginFile(tool, dataDir))).flatMap((row) => {
      const kind = kindFor(tool, row.provider);
