    <UsageDashboard {status} notice={statusError ? notice : undefined} />
  {:else}
    <div class="appbar-wrap">
    <header class="appbar">
      <div class="brand">
        <span class="logo" aria-hidden="true"><i></i><i></i><i></i></span>
