for (const target of releaseTargets) {
  assert.match(target.slug, /^[a-z0-9][a-z0-9-]*$/);
  assert.ok(publicPackages.some((manifest) => manifest.name === target.name), `${target.name} in release-packages.json is not a public workspace`);
